 'use strict';
window.ThingsDiscovery=(()=>{
 const base='https://www.gutenberg.org',q=id=>document.getElementById(id),dialog=el('dialog','sanctuary-dialog discovery-dialog');dialog.id='discovery-dialog';
 const heading=el('div','dialog-heading'),close=el('button','secondary','Close');close.type='button';close.onclick=()=>dialog.close();heading.append(el('h2','','Discover free books'),close);
 const help=el('p','fine','Project Gutenberg public-domain books, through its official OPDS catalog. Availability depends on your country. Searches and downloads contact Gutenberg; your private library and voices are never uploaded.'),label=el('label','catalog-consent'),consent=el('input');consent.type='checkbox';label.append(consent,document.createTextNode(' Allow catalog connections for this visit'));
 const form=el('form','catalog-search'),input=el('input'),search=el('button','primary','Search Gutenberg'),cancel=el('button','secondary','Cancel request'),status=el('p','fine'),results=el('div','catalog-results'),next=el('button','secondary','More results');input.type='search';input.maxLength=160;input.placeholder='Title or author';input.setAttribute('aria-label','Search free books by title or author');search.type='submit';cancel.type=next.type='button';cancel.hidden=next.hidden=true;status.setAttribute('role','status');form.append(input,search,cancel);dialog.append(heading,help,label,form,status,results,next);document.body.append(dialog);
 let controller=null,epoch=0,nextUrl=null,active=false;
 const links=(node)=>[...node.getElementsByTagNameNS('http://www.w3.org/2005/Atom','link')],text=(node,name)=>node.getElementsByTagNameNS('http://www.w3.org/2005/Atom',name)[0]?.textContent.trim()||'';
 function opds(xml){if(xml.length>2*1024*1024||/<!DOCTYPE|<!ENTITY/i.test(xml))throw Error('Invalid catalog response.');const doc=new DOMParser().parseFromString(xml,'application/xml');if(doc.querySelector('parsererror')||doc.documentElement.localName!=='feed')throw Error('Invalid catalog response.');return doc;}
 function urlFor(href){const u=new URL(href,base);if(u.origin!==base||u.username||u.password||u.hash)throw Error('Untrusted catalog link.');return u.href;}
 function clear(){epoch++;controller?.abort();controller=null;active=false;consent.checked=false;input.value='';results.replaceChildren();status.textContent='';nextUrl=null;next.hidden=cancel.hidden=true;search.disabled=false;if(dialog.open)dialog.close();}
 dialog.addEventListener('close',clear);dialog.addEventListener('cancel',clear);
 consent.onchange=()=>{if(!consent.checked){epoch++;controller?.abort();controller=null;active=false;cancel.hidden=true;search.disabled=false;status.textContent='Connections stopped. Select permission before searching again.';}};
 cancel.onclick=()=>{epoch++;controller?.abort();controller=null;active=false;cancel.hidden=true;search.disabled=false;status.textContent='Request cancelled. Your library was not changed.';};
 async function request(url,signal){const response=await fetch('/catalog?url='+encodeURIComponent(url),{signal,credentials:'omit',cache:'no-store',referrerPolicy:'no-referrer'});if(!response.ok)throw Error('The catalog is unavailable or the download exceeds32 MB. Try later.');return response;}
 async function run(task){if(active||!key)return;if(!consent.checked){status.textContent='Allow catalog connections first. Nothing has been sent.';consent.focus();return;}const owner=key,id=++epoch;controller=new AbortController();const signal=controller.signal;active=true;search.disabled=true;cancel.hidden=false;next.disabled=true;const fresh=()=>id===epoch&&key===owner&&dialog.open&&consent.checked;try{await task(signal,fresh);}catch(e){if(fresh())status.textContent=e.name==='AbortError'?'Request cancelled.':e.message||'Could not contact the catalog.';}finally{if(id===epoch){active=false;controller=null;search.disabled=false;cancel.hidden=true;next.disabled=false;}}}
 async function download(item){return run(async(signal,fresh)=>{
  if(busy){status.textContent='Finish the current save first.';return;}status.textContent='Checking available formats…';const doc=opds(await(await request(item.detail,signal)).text());if(!fresh())return;
  const entries=[...doc.getElementsByTagNameNS('http://www.w3.org/2005/Atom','entry')];const choices=[];for(const entry of entries){const rights=[...entry.getElementsByTagName('*')].find(n=>n.localName==='rights')?.textContent||'';if(!/public domain in the usa/i.test(rights))continue;for(const link of links(entry)){if(link.getAttribute('type')==='application/epub+zip'&&link.getAttribute('rel')==='http://opds-spec.org/acquisition'){const url=urlFor(link.getAttribute('href'));if(/^\/ebooks\/[1-9]\d{0,6}\.(?:epub\.(?:images|noimages)|epub3\.images)$/.test(new URL(url).pathname))choices.push({url,label:link.getAttribute('title'),length:Number(link.getAttribute('length'))});}}}
  choices.sort((a,b)=>(a.url.endsWith('.noimages')?-1:1)-(b.url.endsWith('.noimages')?-1:1));const choice=choices.find(c=>!c.length||c.length<=32*1024*1024);if(!choice)throw Error('No supported public-domain EPUB under32 MB is available.');
  status.textContent='Downloading '+item.title+'…';let bytes;try{bytes=new Uint8Array(await(await request(choice.url,signal)).arrayBuffer());if(!fresh())return;if(!bytes.length||bytes.length>32*1024*1024||bytes[0]!==0x50||bytes[1]!==0x4b)throw Error('The server did not return a valid EPUB.');if(busy)throw Error('Another save started. Please try the download again.');const file=new File([bytes],'Gutenberg-'+item.id+'.epub',{type:'application/epub+zip'});dialog.close();openUpload([file]);q('book-title').value=item.title;q('book-author').value=item.author;await upload({preventDefault(){}});}finally{bytes?.fill(0);}
 });}
 async function find(url){return run(async(signal,fresh)=>{status.textContent='Searching Project Gutenberg…';results.replaceChildren();next.hidden=true;const doc=opds(await(await request(url,signal)).text());if(!fresh())return;let count=0;for(const entry of [...doc.getElementsByTagNameNS('http://www.w3.org/2005/Atom','entry')].slice(0,25)){const link=links(entry).find(n=>/\.opds$/.test(n.getAttribute('href')||''));if(!link)continue;const detail=urlFor(link.getAttribute('href')),match=new URL(detail).pathname.match(/^\/ebooks\/([1-9]\d{0,6})\.opds$/);if(!match)continue;const item={id:match[1],detail,title:text(entry,'title').slice(0,300),author:text(entry,'content').slice(0,300)};const row=el('article','catalog-result'),button=el('button','secondary','Download to library');button.type='button';button.onclick=()=>download(item);row.append(el('h3','',item.title),el('p','fine',item.author),el('p','fine','EPUB · public-domain availability checked before download'),button);results.append(row);count++;}const more=links(doc.documentElement).find(n=>n.parentElement===doc.documentElement&&n.getAttribute('rel')==='next');nextUrl=more?urlFor(more.getAttribute('href')):null;next.hidden=!nextUrl;status.textContent=count?'Found '+count+' titles. Downloads use the smaller EPUB where available.':'No matching titles. Try another title or author.';});}
 form.onsubmit=e=>{e.preventDefault();const value=input.value.trim();if(value)find(base+'/ebooks/search.opds/?query='+encodeURIComponent(value));};next.onclick=()=>nextUrl&&find(nextUrl);
 const open=el('button','nav-item','Discover free books');open.id='discover-books';open.type='button';open.onclick=()=>{if(!key)return;dialog.showModal();input.focus();};q('reading-filter').after(open);
 return {clear,opds};
})();
